CREATE TYPE public.app_role AS ENUM ('admin','editor','journalist');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_editor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor') $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', district_id text NOT NULL DEFAULT '', constituency text NOT NULL DEFAULT '', avatar text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_profiles ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_editor());
CREATE POLICY edit_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_newsroom_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name',NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'journalist'); RETURN NEW; END $$;
CREATE TRIGGER newsroom_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_newsroom_profile();
CREATE TABLE public.news (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL, headline text NOT NULL, script text NOT NULL, category text NOT NULL, district_id text NOT NULL, constituency text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','broadcasted','revision','rejected')), importance text NOT NULL DEFAULT 'normal', image text NOT NULL DEFAULT '', clip_paths jsonb NOT NULL DEFAULT '{}', ai_voice boolean NOT NULL DEFAULT false, urgent boolean NOT NULL DEFAULT false, feedback text, views integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.news TO anon; GRANT SELECT,INSERT,UPDATE ON public.news TO authenticated; GRANT ALL ON public.news TO service_role;
ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_news ON public.news FOR SELECT TO anon,authenticated USING(status IN ('approved','broadcasted'));
CREATE POLICY own_news ON public.news FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.is_editor());
CREATE POLICY submit_news ON public.news FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='pending' AND feedback IS NULL AND views=0 AND (public.has_role(auth.uid(),'journalist') OR public.is_editor()));
CREATE POLICY moderate_news ON public.news FOR UPDATE TO authenticated USING(public.is_editor()) WITH CHECK(public.is_editor());
CREATE TABLE public.breaking_news (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), text text NOT NULL, region text NOT NULL, minutes integer NOT NULL DEFAULT 30, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.breaking_news TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.breaking_news TO authenticated; GRANT ALL ON public.breaking_news TO service_role;
ALTER TABLE public.breaking_news ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_breaking ON public.breaking_news FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY manage_breaking ON public.breaking_news FOR ALL TO authenticated USING(public.is_editor()) WITH CHECK(public.is_editor());
CREATE TABLE public.broadcast_settings (id text PRIMARY KEY DEFAULT 'main' CHECK(id='main'), data jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.broadcast_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.broadcast_settings TO authenticated; GRANT ALL ON public.broadcast_settings TO service_role;
ALTER TABLE public.broadcast_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_broadcast ON public.broadcast_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY manage_broadcast ON public.broadcast_settings FOR ALL TO authenticated USING(public.is_editor()) WITH CHECK(public.is_editor());
CREATE POLICY upload_news_clips ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='news-clips' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY read_news_clips ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='news-clips' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_editor() OR EXISTS(SELECT 1 FROM public.news WHERE status IN ('approved','broadcasted') AND clip_paths @> jsonb_build_object(split_part(storage.filename(name),'.',1),name))));
CREATE INDEX news_status_created ON public.news(status,created_at DESC);
CREATE INDEX news_reporter ON public.news(reporter_id);